      /**
       * 创建SP活动级别否定关键词
       */
      async createSpCampaignNegativeKeywords(negatives) {
        const formatMatchType = (mt) => {
          const upper = mt.toUpperCase();
          if (upper.includes("_")) return upper;
          if (upper === "NEGATIVEPHRASE") return "NEGATIVE_PHRASE";
          if (upper === "NEGATIVEEXACT") return "NEGATIVE_EXACT";
          return upper;
        };
        const formattedNegatives = negatives.map((n) => ({
          campaignId: String(n.campaignId),
          keywordText: n.keywordText,
          matchType: formatMatchType(n.matchType || "NEGATIVE_EXACT"),
          state: "ENABLED"
        }));
        const BATCH_SIZE3 = 1e3;
        const BATCH_DELAY_MS2 = 300;
        const allResults = [];
        const totalBatches = Math.ceil(formattedNegatives.length / BATCH_SIZE3);
        log25.info(`[SP API] v199: createSpCampaignNegativeKeywords \u5206\u6279\u5904\u7406: \u603B\u8BA1${formattedNegatives.length}\u4E2A, \u5206${totalBatches}\u6279`);
        for (let batchIdx = 0; batchIdx < totalBatches; batchIdx++) {
          const batch = formattedNegatives.slice(batchIdx * BATCH_SIZE3, (batchIdx + 1) * BATCH_SIZE3);
          log25.debug(`[SP API] v199: \u7B2C${batchIdx + 1}/${totalBatches}\u6279: ${batch.length}\u4E2Acampaign\u7EA7\u5426\u5B9A\u8BCD`);
          try {
            const response = await this.axiosInstance.post("/sp/campaignNegativeKeywords", {
              campaignNegativeKeywords: batch
            }, {
              headers: {
                "Content-Type": "application/vnd.spCampaignNegativeKeyword.v3+json",
                "Accept": "application/vnd.spCampaignNegativeKeyword.v3+json"
              }
            });
            const responseData = response.data.campaignNegativeKeywords || {};
            const successItems = responseData.success || [];
            const errorItems = responseData.error || [];
            for (const s of successItems) {
              allResults.push({
                keywordId: s.campaignNegativeKeywordId || s.keywordId,
                code: "SUCCESS",
                details: "",
                index: s.index !== void 0 ? s.index + batchIdx * BATCH_SIZE3 : void 0
              });
            }
            for (const e of errorItems) {
              const errorMsg = e.errors?.map((err) => {
                const val = err.errorValue || {};
                const errorType = err.errorType || "unknownError";
                const typedError = val[errorType] || val.malformedValueError || val.duplicateValueError || val.otherError || val.entityNotFoundError || val;
                const message = typedError?.message || typedError?.cause?.message || "";
                const trigger = typedError?.cause?.trigger || "";
                const fullDetail = message ? `${errorType}: ${message}${trigger ? ` (trigger: ${trigger})` : ""}` : `${errorType}: ${JSON.stringify(val).substring(0, 200)}`;
                return fullDetail;
              }).join("; ") || "Unknown error";
              const isDuplicateError = errorMsg.includes("duplicateValueError") || errorMsg.includes("DUPLICATE_VALUE");
              if (isDuplicateError) {
                log25.info(`[SP API] v449: \u5426\u5B9A\u8BCD\u5DF2\u5B58\u5728(duplicate)\uFF0C\u89C6\u4E3A\u6210\u529F: index=${e.index}`);
                allResults.push({
                  keywordId: e.campaignNegativeKeywordId || 0,
                  code: "SUCCESS_DUPLICATE",
                  details: "Already exists on Amazon (duplicate)",
                  index: e.index !== void 0 ? e.index + batchIdx * BATCH_SIZE3 : void 0
                });
              } else {
                allResults.push({
                  keywordId: 0,
                  code: "ERROR",
                  details: errorMsg,
                  index: e.index !== void 0 ? e.index + batchIdx * BATCH_SIZE3 : void 0
                });
              }
            }
            if (errorItems.length > 0) {
              log25.warn(`[SP API] v199: \u7B2C${batchIdx + 1}\u6279\u5426\u5B9A\u8BCD\u5931\u8D25\u8BE6\u60C5:`);
              for (const e of errorItems) {
                const errDetail = JSON.stringify(e.errors || e).substring(0, 300);
                const kwText = batch[e.index]?.keywordText || "unknown";
                const campId = batch[e.index]?.campaignId || "unknown";
                log25.warn(`  - \u7D22\u5F15${e.index}: campaignId=${campId}, keyword="${kwText}", \u9519\u8BEF: ${errDetail}`);
              }
            }
            log25.warn(`[SP API] v199: \u7B2C${batchIdx + 1}\u6279\u5B8C\u6210: \u6210\u529F=${successItems.length}, \u5931\u8D25=${errorItems.length}`);
          } catch (err) {
            const errData = err.response?.data;
            log25.warn(`[SP API] v199: \u7B2C${batchIdx + 1}\u6279\u5931\u8D25: status=${err.response?.status}, data=`, JSON.stringify(errData).substring(0, 500));
            for (let i = 0; i < batch.length; i++) {
              allResults.push({
                keywordId: 0,
                code: "BATCH_ERROR",
                details: err.message,
                index: i + batchIdx * BATCH_SIZE3
              });
            }
          }
          if (batchIdx < totalBatches - 1) {
            await new Promise((resolve) => setTimeout(resolve, BATCH_DELAY_MS2));
          }
        }
        const successCount = allResults.filter((r) => r.code === "SUCCESS").length;
        const failCount = allResults.length - successCount;
        log25.warn(`[SP API] v199: campaign\u5426\u5B9A\u8BCD\u521B\u5EFA\u5B8C\u6210: \u603B\u8BA1=${negatives.length}, \u6210\u529F=${successCount}, \u5931\u8D25=${failCount}`);
        return allResults;
      }
