    failedChecks.push(`\u65F6\u6BB5\u6570\u636E\u5BC6\u5EA6\u4E0D\u8DB3: \u5E73\u5747${avgDataPointsPerSlot.toFixed(1)}\u70B9/\u65F6\u6BB5 < ${thresholds.minDataPointsPerSlot}\u70B9/\u65F6\u6BB5`);
