  const avgPredictedCR = predictions.reduce((sum, p) => sum + Number(p.predictedCr), 0) / totalPredictions;
  const avgPredictedCV = predictions.reduce((sum, p) => sum + Number(p.predictedCv), 0) / totalPredictions;
