async function batchApplyOptimization(accountId, userId, applications) {
  const results = [];
  let successCount = 0;
  let failedCount = 0;
  for (const app of applications) {
    const result = await applyOptimization({
      accountId,
      userId,
      ...app
    });
    results.push(result);
    if (result.success) {
      successCount++;
    } else {
      failedCount++;
    }
  }
  return {
    totalCount: applications.length,
    successCount,
    failedCount,
    results
  };
}
