          const [compCount] = await db.select({ count: sql140`COUNT(*)` }).from(prelaunchCompetitors).where(eq127(prelaunchCompetitors.projectId, projectId));
          const [personaCount] = await db.select({ count: sql140`COUNT(*)` }).from(prelaunchPersonas).where(eq127(prelaunchPersonas.projectId, projectId));
          const [copyCount] = await db.select({ count: sql140`COUNT(*)` }).from(prelaunchCopyVersions).where(eq127(prelaunchCopyVersions.projectId, projectId));
