async function createContext(opts) {
  let user = null;
  const url = opts.req.url || "";
  const hasAuth = !!opts.req.headers.authorization;
  logSystem("Context", `createContext called: url=${url.substring(0, 80)}, hasAuth=${hasAuth}`);
  try {
    const AUTH_TIMEOUT_MS = 3e4;
    const authTimeout = new Promise(
      (resolve) => setTimeout(() => {
        logSystem("Context", `authenticateRequest TIMEOUT after ${AUTH_TIMEOUT_MS / 1e3}s for url=${url.substring(0, 50)}`);
        console.error(`[Context] authenticateRequest timeout after ${AUTH_TIMEOUT_MS / 1e3}s, falling back to null user`);
        resolve(null);
      }, AUTH_TIMEOUT_MS)
    );
    user = await Promise.race([
      sdk.authenticateRequest(opts.req),
      authTimeout
    ]);
    logSystem("Context", `authenticateRequest result: hasUser=${!!user}, userId=${user?.id}`);
  } catch (error) {
    logSystem("Context", `authenticateRequest ERROR: ${error.message?.substring(0, 100)}`);
    user = null;
  }
  return {
    req: opts.req,
    res: opts.res,
    user
  };
}
